create table private.crm_legacy_qcrm_records (source_file text not null, entity text not null, source_id text not null, data jsonb not null, imported_at timestamptz not null default now(), primary key(source_file,entity,source_id)); alter table private.crm_legacy_qcrm_records enable row level security; revoke all on private.crm_legacy_qcrm_records from public,anon,authenticated; comment on table private.crm_legacy_qcrm_records is 'Sanitized source archive. No password material. Pending verified status mappings and SO reconciliation; does not feed sales totals.';
